# Run from the package root: Rscript data-raw/qa/04_loss_reconciliation.R
source("data-raw/qa/helpers.R")
suppressMessages({library(dplyr); library(sf)}); options(width=170)
load("data/tornado_exposure.rda"); load("data/tornado_tracks.rda")
raw <- read.csv(qa_spc_csv()) %>% filter(yr>=1996, sg==1) %>% mutate(tornado_id=paste(yr,om,sep="_")) %>% filter(!duplicated(tornado_id) & !duplicated(tornado_id, fromLast=TRUE))
tt <- st_drop_geometry(tornado_tracks) %>% mutate(year=as.integer(substr(tornado_id,1,4)), loss_usd=ifelse(loss_raw_unit=="millions", round(loss_raw*1e6), loss_raw))
cat("== loss reconciliation ==\n")
tor <- tornado_exposure %>% group_by(tornado_id, year) %>% summarise(total=first(property_loss_tornado_total), alloc=sum(property_loss_allocated), n_const=n_distinct(property_loss_tornado_total), .groups="drop")
cat("loss constant within each tornado:", all(tor$n_const==1), "\n")
cat("exposure loss equals harmonized raw loss for every tornado:", isTRUE(all.equal(tor$total, tt$loss_usd[match(tor$tornado_id, tt$tornado_id)])), "\n")
noz <- tt %>% filter(!tornado_id %in% tornado_exposure$tornado_id)
by <- tor %>% group_by(year) %>% summarise(tornadoes=n(), loss_total=sum(total), loss_alloc=sum(alloc), max_abs_diff=max(abs(total-alloc)), n_loss0=sum(total==0), .groups="drop") %>% left_join(noz %>% group_by(year) %>% summarise(noZCTA=n(), noZCTA_loss=sum(loss_usd), .groups="drop"), by="year") %>% mutate(across(c(noZCTA,noZCTA_loss), ~tidyr::replace_na(.x,0)), unalloc_pct=round(100*noZCTA_loss/(loss_total+noZCTA_loss),3))
print(as.data.frame(by %>% mutate(loss_total=signif(loss_total,5), loss_alloc=signif(loss_alloc,5), noZCTA_loss=signif(noZCTA_loss,4), max_abs_diff=signif(max_abs_diff,2))), row.names=FALSE)
cat(sprintf("\nTOTAL (nominal dollars): loss in exposure %s; allocated %s; max per-tornado diff %.3g\n", format(sum(tor$total), big.mark=",", scientific=FALSE), format(sum(tor$alloc), big.mark=",", scientific=FALSE), max(abs(tor$total-tor$alloc))))
cat(sprintf("no-ZCTA tornadoes: %d (%d with loss>0), unallocated loss %s = %.4f%% of all loss\n", nrow(noz), sum(noz$loss_usd>0), format(sum(noz$loss_usd), big.mark=",", scientific=FALSE), 100*sum(noz$loss_usd)/(sum(tor$total)+sum(noz$loss_usd))))
cat(sprintf("tornadoes with loss==0: in exposure %d of %d; no-ZCTA %d of %d; all %d of %d\n", sum(tor$total==0), nrow(tor), sum(noz$loss_usd==0), nrow(noz), sum(tt$loss_usd==0), nrow(tt)))
cat("by era, share of tornadoes with loss==0:\n"); print(tt %>% mutate(era=ifelse(year<=2006,"1996-2006","2007+")) %>% group_by(era) %>% summarise(tornadoes=n(), loss0=sum(loss_usd==0), pct=round(100*mean(loss_usd==0),1)))
cat("\n== LOSS RELIABILITY (SPC raw, all tornadoes) ==\n")
r <- raw %>% mutate(loss_usd=ifelse(yr<=2006, round(loss*1e6), loss), mag2=ifelse(mag==-9, NA, mag))
cat("EF4+EF5 tornadoes since 2007:", sum(r$yr>=2007 & r$mag %in% 4:5), " with loss 0:", sum(r$yr>=2007 & r$mag %in% 4:5 & r$loss==0), "\n")
cat("EF4+EF5 tornadoes since 1996 (all years):", sum(r$mag %in% 4:5), " with loss 0:", sum(r$mag %in% 4:5 & r$loss==0), "\n")
cat("tornadoes with >=1 fatality since 2007:", sum(r$yr>=2007 & r$fat>=1), " with loss 0:", sum(r$yr>=2007 & r$fat>=1 & r$loss==0), "; with >=10 fatalities:", sum(r$yr>=2007 & r$fat>=10), " with loss 0:", sum(r$yr>=2007 & r$fat>=10 & r$loss==0), "\n")
print(r %>% filter(yr>=2007, fat>=10) %>% arrange(desc(fat)) %>% transmute(tornado_id, st, mag, fat, inj, loss) %>% head(12), row.names=FALSE)
for (id in c("2021_2112102054-01","2011_1104271719-01")) { x <- r %>% filter(tornado_id==id); cat("\nSPC", id, ": "); print(x %>% select(tornado_id, st, date, mag, fat, inj, loss, len, wid, slat, slon, elat, elon), row.names=FALSE) }
